<?php
require_once __DIR__.'/app/lib/Security.php';Security::start();Security::requireRole(['admin','data_editor','reviewer','super_admin']);
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Software Management · TechSelectAI</title><style>body{font-family:Inter,system-ui,sans-serif;background:#f6f8fb;color:#172033;margin:0}main{max-width:1240px;margin:auto;padding:28px}.toolbar,.filters,.tabs,.actions{display:flex;gap:10px;flex-wrap:wrap}.toolbar{justify-content:space-between;align-items:center}.filters{margin:18px 0}.filters input,.filters select,input,select,textarea{padding:9px;border:1px solid #cbd5e1;border-radius:8px;background:#fff}table{width:100%;border-collapse:collapse;background:#fff;border:1px solid #e2e8f0;border-radius:14px;overflow:hidden}th,td{padding:10px;border-bottom:1px solid #eef2f7;text-align:left;vertical-align:top}.muted{color:#64748b;font-size:12px}.badge{display:inline-block;padding:4px 8px;border-radius:999px;background:#eef2ff;font-size:12px}.btn,button{border:0;border-radius:8px;padding:9px 12px;background:#173b63;color:#fff;text-decoration:none;cursor:pointer}.secondary{background:#64748b}.danger{background:#9f2d2d}.drawer{position:fixed;inset:0 0 0 auto;width:min(760px,100%);background:#fff;box-shadow:-12px 0 30px rgba(15,23,42,.16);padding:24px;overflow:auto;display:none;z-index:20}.drawer.open{display:block}.grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}.tabs button{background:#eef2f6;color:#172033}.tabs button.active{background:#173b63;color:white}.panel{display:none;margin-top:16px}.panel.active{display:block}.check{padding:9px;border-bottom:1px solid #eef2f7}.ok{color:#166534}.bad{color:#b91c1c}@media(max-width:700px){main{padding:16px}.grid{grid-template-columns:1fr}table{display:block;overflow:auto}}</style></head><body><main><div class="toolbar"><div><h1>Software Management</h1><div class="muted">Search, edit, review readiness and manage lifecycle.</div></div><a class="btn secondary" href="/admin">Admin Overview</a></div><div class="filters"><input id="q" placeholder="Search software/vendor"><select id="status"><option value="">All status</option><option>active</option><option>draft</option><option>archived</option></select><select id="vendor"><option value="">All vendors</option></select><select id="category"><option value="">All categories</option></select><button onclick="load()">Filter</button><button class="secondary" onclick="bulk('draft')">Bulk draft</button><button class="danger" onclick="bulk('archived')">Bulk archive</button></div><table><thead><tr><th></th><th>Software</th><th>Vendor / Category</th><th>Status</th><th>Evidence</th><th>Evaluation</th><th>Readiness</th><th></th></tr></thead><tbody id="rows"></tbody></table></main><aside id="drawer" class="drawer"><div class="toolbar"><h2 id="dtitle">Software</h2><button class="secondary" onclick="closeDrawer()">Close</button></div><div id="drawerBody"></div></aside><script>
let csrf='',refs={vendors:[],categories:[]},current=null;function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}async function api(url,opt={}){opt.headers={...(opt.headers||{}),'Content-Type':'application/json','X-CSRF-Token':csrf};let r=await fetch(url,opt),d=await r.json().catch(()=>({}));if(!r.ok)throw Object.assign(new Error(d.error||'Request failed'),{data:d});return d}
async function load(){let p=new URLSearchParams();for(let id of ['q','status','vendor','category']){let v=document.getElementById(id).value;if(v)p.set(id==='vendor'?'vendor_id':id==='category'?'category_id':id,v)}let d=await api('/api/software-management?'+p);csrf=d.csrf_token;refs=d.reference;fillRefs();document.getElementById('rows').innerHTML=d.products.map(x=>`<tr><td><input type="checkbox" class="sel" value="${x.id}"></td><td><strong>${esc(x.name)}</strong><br><span class="muted">${esc(x.slug)}</span></td><td>${esc(x.vendor||'—')}<br><span class="muted">${esc(x.category||'—')}</span></td><td><span class="badge">${esc(x.status)}</span></td><td>${x.evidence_count} total / ${x.evidence_issues} issues</td><td>${x.evaluation_count?esc(x.evaluation_at||'Published'):'Missing'}</td><td><strong>${x.readiness.score}%</strong><br><span class="muted">${x.readiness.passed}/${x.readiness.total} checks</span></td><td><button onclick="openProduct(${x.id})">Manage</button></td></tr>`).join('')}
function fillRefs(){document.getElementById('vendor').innerHTML='<option value="">All vendors</option>'+refs.vendors.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('');document.getElementById('category').innerHTML='<option value="">All categories</option>'+refs.categories.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('')}
async function openProduct(id){let d=await api('/api/software-management/'+id);csrf=d.csrf_token;current=d.product;refs=d.reference;document.getElementById('dtitle').textContent=current.name;renderDetail();document.getElementById('drawer').classList.add('open')}
function closeDrawer(){document.getElementById('drawer').classList.remove('open');current=null}
function rows(arr,cols){if(!arr||!arr.length)return '<p class="muted">No records.</p>';return '<table><tbody>'+arr.map(r=>'<tr>'+cols.map(c=>`<td>${esc(r[c]??'')}</td>`).join('')+'</tr>').join('')+'</tbody></table>'}
function renderDetail(){let p=current,r=p.readiness;document.getElementById('drawerBody').innerHTML=`<div class="tabs">${['overview','capabilities','pricing','integrations','deployment','evidence','community','evaluation','seo','history'].map((t,i)=>`<button class="${i?'':'active'}" onclick="tab('${t}',this)">${t}</button>`).join('')}</div><section id="overview" class="panel active"><div class="grid"><label>Name<input id="name" value="${esc(p.name)}"></label><label>Status<select id="pstatus"><option ${p.status==='draft'?'selected':''}>draft</option><option ${p.status==='active'?'selected':''}>active</option><option ${p.status==='archived'?'selected':''}>archived</option></select></label><label>Vendor<select id="pvendor"><option value="">—</option>${refs.vendors.map(x=>`<option value="${x.id}" ${+x.id===+p.vendor_id?'selected':''}>${esc(x.name)}</option>`).join('')}</select></label><label>Category<select id="pcat"><option value="">—</option>${refs.categories.map(x=>`<option value="${x.id}" ${+x.id===+p.category_id?'selected':''}>${esc(x.name)}</option>`).join('')}</select></label></div><label>Website<input id="url" value="${esc(p.website_url||'')}"></label><label>Description<textarea id="desc">${esc(p.short_description||'')}</textarea></label><p><a href="/software/${esc(p.slug)}" target="_blank">View public page</a></p><div class="actions"><button onclick="save()">Save changes</button></div><h3>Publishing readiness · ${r.score}%</h3>${Object.values(r.checks).map(c=>`<div class="check ${c.ok?'ok':'bad'}">${c.ok?'✓':'✕'} ${esc(c.label)} ${c.value!==undefined?`<span class="muted">(${esc(c.value)})</span>`:''}</div>`).join('')}</section><section id="capabilities" class="panel">${rows(p.capabilities,['name','support_status','confidence_score','last_verified_at'])}</section><section id="pricing" class="panel">${rows(p.pricing,['edition_name','pricing_model','billing_period','currency','amount_min','amount_max','last_verified_at'])}</section><section id="integrations" class="panel">${rows(p.integrations,['name','support_status','confidence_score','last_verified_at'])}</section><section id="deployment" class="panel">${rows(p.deployments,['name','support_status','confidence_score','last_verified_at'])}</section><section id="evidence" class="panel">${rows(p.evidence,['source_title','source_type','verification_status','confidence','checked_at'])}</section><section id="community" class="panel">${rows(p.community,['publication_status','confidence_score','updated_at'])}</section><section id="evaluation" class="panel">${rows(p.evaluations,['methodology_version','overall_score','confidence_score','status','evaluated_at'])}</section><section id="seo" class="panel"><p>Slug: <code>${esc(p.slug)}</code></p><p>Public URL: <a href="/software/${esc(p.slug)}" target="_blank">/software/${esc(p.slug)}</a></p><p>Readiness basics: ${r.checks.seo.ok?'Ready':'Blocked'}</p></section><section id="history" class="panel">${rows(p.history,['created_at','action','actor_user_id'])}</section>`}
function tab(id,b){document.querySelectorAll('.panel').forEach(x=>x.classList.remove('active'));document.querySelectorAll('.tabs button').forEach(x=>x.classList.remove('active'));document.getElementById(id).classList.add('active');b.classList.add('active')}
async function save(){try{let body={name:name.value,status:pstatus.value,vendor_id:pvendor.value||null,category_id:pcat.value||null,website_url:url.value,short_description:desc.value};let d=await api('/api/software-management/'+current.id,{method:'PATCH',body:JSON.stringify(body)});current=d.product;renderDetail();await load();alert('Saved')}catch(e){alert(e.message+(e.data?.readiness?' · readiness '+e.data.readiness.score+'%':''))}}
async function bulk(status){let ids=[...document.querySelectorAll('.sel:checked')].map(x=>+x.value);if(!ids.length)return alert('Select products first');if(!confirm(`Set ${ids.length} products to ${status}?`))return;await api('/api/software-management/bulk-status',{method:'POST',body:JSON.stringify({product_ids:ids,status})});await load()}
load();
</script></body></html>